const reduced=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches||!!store.reduceMotion;
let viewCleanup=()=>{}, graphView=null, fullGraphView=null, peopleViewController=null;
function viewSnapshot(){return {route:S.route,date:S.date,homeMode:S.homeMode,groupFilter:S.groupFilter,expandedBlock:S.expandedBlock,blockId:S.blockId||null,scrollTop:$('#content').scrollTop,peopleWindow:clone(S.peopleWindow),focus:S.focus,peopleOrder:clone(S.peopleOrder),peoplePin:S.peoplePin||null,peopleStable:!!S.peopleStable,person:S.person,analysisId:S.analysisId||null,personTab:S.personTab||'理解',scene:S.scene,sceneFilter:S.sceneFilter,tab:S.tab,selectedEpisode:S.selectedEpisode,recordTab:S.recordTab||'记录',highlight:S.highlight||null,scope:clone(S.scope),graphScope:clone(S.graphScope||{kind:'all'}),calendarDate:S.calendarDate,calendarFilter:S.calendarFilter||'all',calendarMonthOpen:!!S.calendarMonthOpen,search:S.search||''}}
