 if(S.graphFull){closeFullGraph();return}
 if(S.sheet){closeSheet();return}
 const p=S.stack.pop();if(p){const {scrollTop=0,...state}=p;Object.assign(S,state);render();$('#content').scrollTop=scrollTop}else{S.route='home';render()}
