function deviceStrip(){return `<div class="device-record-row"><button type="button" data-act="device" class="device-strip"><span class="sample-tag">示例</span><img class="device-photo" src="${PRODUCT}" alt="soundcore Work 3200"><span class="device-info"><strong>Work 3200</strong><small>${S.connected?'已连接 · 84%':'连接中断 · 待核实'}${S.record==='recording'?' · 记录中':''}</small></span>${icon('chevron')}</button>${b('record',icon(S.record==='recording'?'wave':'mic')+(S.record==='recording'?' 录音中':' 记录'),'record-button')}</div>`}
function dateControls(){const all=S.date==='all',d=all?DATA.dates[0]:S.date,weekday=['日','一','二','三','四','五','六'][new Date(d+'T12:00:00').getDay()];return `<div class="date-row"><button type="button" data-act="date-picker" class="date-heading" aria-label="选择日期"><span class="date-main">${all?'两天':`10月${d.slice(-2)}日`}</span>${all?'':`<span class="date-week">周${weekday}</span>`}${icon('down')}</button><span class="grow"></span>${b('recap',icon('spark')+' 复盘','text-button')}</div>`}
function homeTabs(){return `<div class="segmented" role="tablist" aria-label="总览视角">${b('home-mode',icon('timeline')+' 时间线',S.homeMode==='time'?'active':'','data-mode="time" role="tab" aria-selected="'+(S.homeMode==='time')+'"')}${b('home-mode',icon('people')+' 人物交汇',S.homeMode==='people'?'active':'','data-mode="people" role="tab" aria-selected="'+(S.homeMode==='people')+'"')}</div>`}
function blockPeople(block){return [...new Set(block.items.flatMap(e=>e.participants))]}
function blockCard(block){
 const open=S.expandedBlock===block.id;const ps=blockPeople(block);const isNight=block.scene==='夜间';
  return `<article class="scene-block ${open?'expanded':''}" data-block="${block.id}" data-tone="${block.tone}"><div class="block-shell"><button type="button" class="block-head" data-act="toggle-block" data-id="${block.id}" aria-expanded="${open}" aria-controls="body-${block.id}"><span class="block-time"><time>${block.start}—${block.end}</time><span>${isNight?'后续预览':block.scene}</span></span><span class="block-title"><strong>${esc(block.title)}</strong>${icon('chevron')}</span><span class="block-meta"><span class="block-label">${esc(block.label)}</span>${!open&&ps.length?`<span class="avatar-row">${ps.slice(0,2).map(av).join('')}${ps.length>2?`<span class="avatar-count">+${ps.length-2}</span>`:''}</span>`:''}<span class="event-count">${block.items.length} 件事</span></span></button>${open?`<div class="block-body" id="body-${block.id}"><div class="inner-events">${block.items.map(e=>innerEvent(e)).join('')}</div><div class="block-foot">${b(isNight?'sleep':'block-detail',icon('arrow')+' 完整回看','text-button',`data-id="${block.id}"`)}${!isNight?b('ask-block',icon('chat')+' 聊这段时间','text-button',`data-id="${block.id}"`):''}</div></div>`:''}</div></article>`;
}
function innerEvent(e){
 const ps=e.participants.map(id=>person(id).name).join('、');const type=sceneName(e.kind);
 const peek=e.items?.find(x=>x)||e.summary;let rid=e.itemRefs?.[0]?.[0]||DATA.refs.find(r=>r.recordingId===e.id)?.id;
  return `<div class="inner-event" data-event="${e.id}"><button type="button" class="inner-title" data-act="${e.status==='preview'?'sleep':'episode'}" data-id="${e.id}"><time>${shortTime(e.start)}</time><span class="event-heading"><strong>${esc(eventTitle(e))}</strong><small>${esc(ps|| (e.source==='manual_private_gap'?'仅本人补记':e.source==='manual_with_audio_fixture'?'本人记录':type))}</small></span>${icon('chevron')}</button><div class="inner-detail"><span class="inner-detail-text">${esc(peek.length>90?peek.slice(0,90)+'…':peek)}</span>${e.status!=='preview'&&e.segments.length&&rid?`<span class="inner-citation">${ref(rid,'原话')}</span>`:''}</div></div>`;
}
