function peopleMinuteOf(stamp){return +stamp.slice(11,13)*60+ +stamp.slice(14,16)}
function palePersonColor(color){const hex=color?.replace('#','')||'7b8973';if(hex.length!==6)return '#C8D6C9';const n=parseInt(hex,16),r=n>>16,g=(n>>8)&255,b=n&255;return `#${[r,g,b].map(v=>Math.round(v*.34+255*.66).toString(16).padStart(2,'0')).join('')}`}
function analysisForPerson(id){const explicit=(DATA.interpretations||[]).find(x=>x.id===S.analysisId&&x.personId===id);return explicit||(DATA.interpretations||[]).find(x=>x.personId===id)}
function candidateState(id){return store.candidateChoices?.[id]||null}
function analysisAnchor(an){return UI_QUOTE_ANCHORS[an.id]||an.quoteRef}
function analysisRef(id){const resolved=C.resolveRef(DATA,id,{kind:'all'});if(!resolved.ok)return `<span class="source-unavailable">来源不可用：${esc(resolved.reason)}</span>`;const r=resolved.ref.locator,stamp=n=>`${two(Math.floor(n/60000))}:${two(Math.floor(n/1000)%60)}`;return `<span class="analysis-reference">${ref(id,ANALYSIS_REF_NUMBERS[id]||'原话')}<time>${stamp(r.start_ms)}–${stamp(r.end_ms)}</time></span>`}
function candidateMarkup(an,c,index){const selected=candidateState(an.id)===c.id,rejected=(store.rejectedCandidates||[]).includes(an.id+':'+c.id),refs=c.refs.map(analysisRef).join(' '),choice=b('select-candidate',selected?'已选择':'选择此理解',`candidate-choice ${selected?'selected':''}`,`data-analysis="${an.id}" data-id="${c.id}" aria-pressed="${selected}"`),reject=b('reject-candidate',rejected?'撤销否定':'不符合','text-button',`data-analysis="${an.id}" data-id="${c.id}" aria-pressed="${rejected}"`),content=`<p>${esc(c.reason)}</p><div class="candidate-refs">${refs}</div><div class="actions-row">${choice}${reject}</div>${rejected?'<p class="sub">已标记不符合 · 不采纳此解释</p>':''}`;if(c.support==='依据不足')return `<details class="candidate-card insufficient-card" data-candidate="${c.id}"><summary><span><span class="tag amber">依据不足</span><strong>${esc(c.label)}</strong></span>${icon('chevron')}</summary><div class="candidate-content">${content}</div></details>`;return `<article class="candidate-card ${index===0?'candidate-feature':''}" data-candidate="${c.id}"><div class="candidate-head"><div><span class="tag ${index===0?'support-tag':''}">${esc(c.support||'可继续核对')}</span><strong>${esc(c.label)}</strong></div>${selected?`<span class="selection-check" aria-label="已选择">${icon('check')}</span>`:''}</div><div class="candidate-content">${content}</div></article>`}
